package android.media;
import javax.sound.sampled.*;import javax.swing.SwingUtilities;
public class MediaPlayer {
 public interface Prepared{void run(MediaPlayer m);}public interface Completion{void run(MediaPlayer m);}public interface Error{boolean run(MediaPlayer m,int w,int e);}
 static final java.util.concurrent.ExecutorService loader=java.util.concurrent.Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"Audio loader");t.setDaemon(true);return t;});
 volatile Clip clip;volatile boolean released,loop,playing;int pausedFrame=-1;float volume=1;String path;Prepared prepared;Completion completion;Error error;
 public void setAudioAttributes(AudioAttributes a){}public void setDataSource(String p){path=p;}public void setLooping(boolean b){loop=b;}public void setVolume(float l,float r){volume=Math.max(0,Math.min(1,(l+r)/2));Clip c=clip;if(c!=null&&c.isControlSupported(FloatControl.Type.MASTER_GAIN)){FloatControl gain=(FloatControl)c.getControl(FloatControl.Type.MASTER_GAIN);gain.setValue(Math.max(gain.getMinimum(),Math.min(gain.getMaximum(),volume==0?gain.getMinimum():(float)(20*Math.log10(volume)))));}}
 public void setOnPreparedListener(Prepared p){prepared=p;}public void setOnCompletionListener(Completion c){completion=c;}public void setOnErrorListener(Error e){error=e;}
 public void prepareAsync(){loader.execute(()->{Clip c=null;try(AudioInputStream stream=AudioSystem.getAudioInputStream(new java.io.File(path))){c=AudioSystem.getClip();c.open(stream);Clip ready=c;SwingUtilities.invokeLater(()->{if(released){ready.close();return;}clip=ready;setVolume(volume,volume);ready.addLineListener(event->{if(event.getType()==LineEvent.Type.STOP&&playing&&!loop&&ready.getFramePosition()>=ready.getFrameLength()-1){playing=false;SwingUtilities.invokeLater(()->{if(!released&&completion!=null)completion.run(this);});}});if(prepared!=null)prepared.run(this);});}catch(Exception ex){if(c!=null)c.close();SwingUtilities.invokeLater(()->{if(!released&&error!=null)error.run(this,0,0);});}});}
 public void start(){Clip c=clip;if(c==null||released)return;if(pausedFrame>=0){c.setFramePosition(pausedFrame);pausedFrame=-1;}playing=true;if(loop)c.loop(Clip.LOOP_CONTINUOUSLY);else c.start();}public void pause(){playing=false;if(clip!=null){clip.stop();pausedFrame=clip.getFramePosition();}}public void release(){released=true;playing=false;if(clip!=null){clip.stop();clip.close();}}
}
